let progress=0,playing=false,stage=-1,rx=.20,ry=-.13,zoom=1,last=0;
stages.forEach((s,i)=>{let b=document.createElement('button');b.textContent=i+1;b.setAttribute('aria-label',s[0]);b.onclick=()=>setProgress([0,25,45,85][i]);$('steps').append(b)});
function setProgress(p){progress=Math.max(0,Math.min(100,p));$('timeline').value=progress;$('percent').textContent=Math.round(progress)+'%';const n=progress<25?0:progress<45?1:progress<85?2:3;if(n!==stage){stage=n;$('stepCount').textContent='STEP 0'+(n+1);$('stepTitle').textContent=stages[n][0];$('stepEnglish').textContent=stages[n][1];$('stepText').textContent=stages[n][2];$('observe').textContent=stages[n][3];[...$('steps').children].forEach((b,i)=>{b.classList.toggle('active',i===n);b.setAttribute('aria-current',i===n?'step':'false')});$('next').textContent=n===3?'回到第一步':'下一步'}if(progress>=100){playing=false;$('play').textContent='重播'}if(window.updateExperiment)window.updateExperiment();draw()}
$('next').onclick=()=>{playing=false;$('play').textContent='播放';setProgress([0,25,45,85][(stage+1)%4])};$('timeline').oninput=e=>{playing=false;$('play').textContent='播放';setProgress(+e.target.value)};$('play').onclick=()=>{if(progress>=100)setProgress(experiment.mode === 'normal' ? 0 : 25);playing=!playing;$('play').textContent=playing?'暂停':'播放'};$('restart').onclick=()=>{playing=false;$('play').textContent='播放';setProgress(0)};$('resetView').onclick=()=>{rx=.20;ry=-.13;zoom=1;draw()};$('labels').onchange=draw;$('arrows').onchange=draw;
const facts=[['解旋酶','Helicase · 分开双链，使模板暴露。模型中的蓝色环位于复制叉附近。'],['DNA 聚合酶','DNA polymerase · 从已有引物的 3′ 端延伸新链。浅色圆形表示活跃的聚合酶，点击模型也可查看。'],['RNA 引物','RNA primer · 粉色短段提供起点，之后被移除并替换成 DNA。'],['冈崎片段','Okazaki fragment · 滞后链上分别起始、沿 5′→3′ 方向延伸的短 DNA 片段。'],['DNA 连接酶','DNA ligase · 在引物移除且缺口填入 DNA 后，封闭相邻 DNA 片段之间的骨架缺口。']];
function showFact(i){$('detail').textContent=facts[i][1];[...$('structures').children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-pressed',i===j)})}facts.forEach((f,i)=>{let b=document.createElement('button');b.textContent=f[0];b.onclick=()=>{showFact(i);if(i===0&&window.openMicro)window.openMicro()};$('structures').append(b)});showFact(0);
const qs=[{q:'如果 DNA 聚合酶只能向 3′ 端添加核苷酸，滞后链会怎样合成？',a:['沿 3′→5′ 连续合成','沿 5′→3′ 分段合成','等待前导链完成后再反向合成'],c:1,why:'每个冈崎片段都沿 5′→3′ 合成。分段起始解决了模板方向与复制叉推进方向不一致的问题。'},{q:'如果引物酶停止工作，新的冈崎片段还能开始合成吗？',a:['不能：缺少可供延伸的引物 3′ 端','能：DNA 聚合酶会自行起始','能：连接酶会代替引物酶'],c:0,why:'DNA 聚合酶需要已有的引物 3′ 端。已经起始的片段可能继续延伸，但新片段无法正常起始。'},{q:'半保留复制完成后，每个子代 DNA 双链包含什么？',a:['两条全新的链','两条原有的亲代链','一条亲代链与一条新合成链'],c:2,why:'两条亲代链分别充当模板，每个子代 DNA 都保留其中一条，并配对一条新合成链。'}];let qi=0;
function quiz(){const q=qs[qi];$('quizCount').textContent='0'+(qi+1)+' / 03';$('question').textContent=q.q;$('answers').replaceChildren();$('feedback').textContent='';$('nextQuiz').hidden=true;q.a.forEach((a,i)=>{const b=document.createElement('button');b.textContent=String.fromCharCode(65+i)+'  '+a;b.onclick=()=>{[...$('answers').children].forEach((x,j)=>{x.disabled=true;x.classList.toggle('correct',j===q.c);x.classList.toggle('wrong',j===i&&i!==q.c)});$('feedback').textContent=(i===q.c?'答对了。':'再想一想。')+q.why;$('nextQuiz').hidden=false;$('nextQuiz').textContent=qi===2?'再练一次':'下一题'};$('answers').append(b)})}$('nextQuiz').onclick=()=>{qi=(qi+1)%3;quiz()};quiz();
const canvas=$('model'),ctx=canvas.getContext('2d');let width=700,height=390,hits=[];
function resize(){let b=canvas.getBoundingClientRect();width=b.width;height=b.height;canvas.width=width*devicePixelRatio;canvas.height=height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);draw()}new ResizeObserver(resize).observe(canvas);
function project(x,y,z){let a=y*Math.cos(rx)-z*Math.sin(rx),b=y*Math.sin(rx)+z*Math.cos(rx),c=x*Math.cos(ry)+b*Math.sin(ry),d=-x*Math.sin(ry)+b*Math.cos(ry);let s=Math.min(width/750,height/360)*zoom*700/(700+d);return [width/2+c*s,height/2+a*s,s,d]}
function line(a,b,color,size=3){const p=project(...a),q=project(...b);ctx.strokeStyle=color;ctx.lineWidth=size*(p[2]+q[2])/2;ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);ctx.stroke()}
function ball(p,color,r=5){const a=project(...p),rr=r*a[2];let g=ctx.createRadialGradient(a[0]-rr*.3,a[1]-rr*.3,0,a[0],a[1],rr);g.addColorStop(0,'#ffffff');g.addColorStop(.3,color);g.addColorStop(1,color);ctx.fillStyle=g;ctx.beginPath();ctx.arc(a[0],a[1],rr,0,Math.PI*2);ctx.fill()}
function label(p,text,color='#c9d9e8'){const a=project(...p);ctx.font='13px "Segoe UI","Microsoft YaHei",sans-serif';ctx.textAlign='center';ctx.fillStyle='#101f30e6';const w=ctx.measureText(BioI18n.t(text)).width;ctx.fillRect(a[0]-w/2-5,a[1]-12,w+10,20);ctx.fillStyle=color;ctx.fillText(BioI18n.t(text),a[0],a[1]+3)}
function arrow(a,b,color){line(a,b,color,2);let p=project(...a),q=project(...b),ang=Math.atan2(q[1]-p[1],q[0]-p[0]);ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(q[0],q[1]);ctx.lineTo(q[0]-10*Math.cos(ang-.5),q[1]-10*Math.sin(ang-.5));ctx.lineTo(q[0]-10*Math.cos(ang+.5),q[1]-10*Math.sin(ang+.5));ctx.fill()}
function forkX(){return -95+Math.min(progress/85,1)*245}function strand(x,sign,offset=0){let f=forkX();if(x<=f){let spread=Math.min((f-x)*.46,87);return [x,sign*(18+spread)+offset,Math.sin((x-f)/31)*9]}let angle=(x-f)/28;return [x,sign*18*Math.cos(angle),sign*18*Math.sin(angle)]}
function draw(){if(!ctx)return;ctx.clearRect(0,0,width,height);hits=[];ctx.fillStyle='#ffffff04';for(let x=20;x<width;x+=28)for(let y=20;y<height;y+=28){ctx.beginPath();ctx.arc(x,y,1,0,7);ctx.fill()}let f=forkX();const top='#91a6c3',green='#5ce0bd',orange='#ffba73',pink='#eb88c5';
 for(let s of [-1,1])for(let x=-285;x<290;x+=5){line(strand(x,s),strand(x+5,s),top,3.6);if(x%10===0)ball(strand(x,s),top,3)}
 for(let x=Math.ceil(f/12)*12;x<=285;x+=12){line(strand(x,-1),strand(x,1),'#637b95',2);ball(strand(x,-1),top,3);ball(strand(x,1),top,3)}
 // All coordinates describe one right-moving fork. Upper template: 3′ left / 5′ right.
 const primed=progress>=25,elong=Math.max(0,Math.min(1,(progress-45)/40)),finish=Math.max(0,(progress-85)/15);let leadEnd=-260+(f+242)*elong;
 if(primed){for(let x=-272;x<-258;x+=4)line(strand(x,-1,18),strand(x+4,-1,18),finish>.15?green:pink,5);if(progress>=45){for(let x=-258;x<leadEnd;x+=4){line(strand(x,-1,18),strand(Math.min(x+4,leadEnd),-1,18),green,4);if(x%12===-6)line(strand(x,-1),strand(x,-1,18),'#5ce0bd66',1)}if(progress<85){ball(strand(leadEnd,-1,18),green,11);hits.push({p:project(...strand(leadEnd,-1,18)),i:1})}}}
 const ends=[-193,-108,-23,62,132];ends.forEach((end,j)=>{const reveal=25+j*11;if(progress<reveal||end>f-8||(activeCondition()==='primase'&&j>0))return;let growth=Math.max(0,Math.min(1,(progress-(45+j*6))/10)),start=end-62*growth;for(let x=end-10;x<end;x+=3)line(strand(x,1,-18),strand(x+3,1,-18),finish>(j+1)/7?orange:pink,5);if(growth>0){for(let x=start;x<end-10;x+=4)line(strand(x,1,-18),strand(Math.min(x+4,end-10),1,-18),orange,4);if(growth<1&&progress<85){ball(strand(start,1,-18),orange,10);hits.push({p:project(...strand(start,1,-18)),i:1})}if($('arrows').checked&&growth>.4){arrow(strand(end-5,1,15),strand(start,1,15),orange);if($('labels').checked){label(strand(end,1,35),'5′',orange);label(strand(start,1,35),'3′',orange)}}if(j>0&&finish>j/6){for(let x=ends[j-1];x<end-62;x+=3){const nick=ends[j-1]+9;if(activeCondition()!=='ligase'||Math.abs(x-nick)>4)line(strand(x,1,-18),strand(Math.min(x+3,end-62),1,-18),orange,4)}}}});
 if(activeCondition()==='ligase'&&finish>.8){for(let j=1;j<ends.length;j++){let p=strand(ends[j-1]+9,1,-18),a=project(...p);ctx.strokeStyle='#ff7788';ctx.lineWidth=2;ctx.beginPath();ctx.arc(a[0],a[1],9*a[2],0,Math.PI*2);ctx.stroke()}if($('labels').checked)label([-130,153,0],'圈出骨架断口（放大示意）','#ff9ea9')}
 let hp=project(f,0,0);ctx.strokeStyle='#77bafa';ctx.lineWidth=9*hp[2];ctx.beginPath();ctx.ellipse(hp[0],hp[1],14*hp[2],27*hp[2],-.2,0,Math.PI*2);ctx.stroke();hits.push({p:hp,i:0});
 if($('arrows').checked){arrow([f+10,-58,0],[f+73,-58,0],'#7fbbf6');if(progress>=45&&leadEnd>-200)arrow(strand(-245,-1,-25),strand(leadEnd,-1,-25),green)}
 if($('labels').checked){label([-290,-128,0],'模板 3′');label([-290,128,0],'模板 5′');label([289,-40,0],'5′');label([289,40,0],'3′');label([f,58,0],'解旋酶','#91caff');label([f+33,-83,0],'复制叉推进','#91caff');if(primed){label([-245,-60,0],'前导链 · Leading',green);label([-180,62,0],'滞后链 · Lagging',orange);label(strand(-269,-1,36),'5′',green);if(progress>=45)label(strand(leadEnd,-1,36),'3′',green)}}
}
let pointer=null,moved=false;canvas.onpointerdown=e=>{pointer=[e.clientX,e.clientY];moved=false;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!pointer)return;let dx=e.clientX-pointer[0],dy=e.clientY-pointer[1];if(Math.abs(dx)+Math.abs(dy)>2)moved=true;ry+=dx*.006;rx=Math.max(-1.2,Math.min(1.2,rx+dy*.006));pointer=[e.clientX,e.clientY];draw()};canvas.onpointerup=e=>{pointer=null;if(!moved){const b=canvas.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;const h=hits.find(h=>Math.hypot(h.p[0]-x,h.p[1]-y)<28);if(h){showFact(h.i);if(h.i===0&&window.openMicro)window.openMicro()}}};canvas.onpointercancel=()=>pointer=null;canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(1.8,zoom-e.deltaY*.001));draw()},{passive:false});canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','='].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')ry-=.1;if(e.key==='ArrowRight')ry+=.1;if(e.key==='ArrowUp')rx-=.1;if(e.key==='ArrowDown')rx+=.1;if(e.key==='+'||e.key==='=')zoom=Math.min(1.8,zoom+.1);if(e.key==='-')zoom=Math.max(.65,zoom-.1);draw()}};
function animate(t){if(playing&&last)setProgress(progress+Math.min(t-last,100)*.003*+$('speed').value);last=t;requestAnimationFrame(animate)}setProgress(0);requestAnimationFrame(animate);

